var FLOORBIT_CAP=240, FLOORBIT_ATLAS=null;
function floorBitHash(n){ n=Math.imul(n^(n>>>16),0x45d9f3b); n=Math.imul(n^(n>>>16),0x45d9f3b); return ((n^(n>>>16))>>>0)/4294967296; }
function floorBitState(){
  if(!G||G.sim||!G.map) return null;
