  var s=G.floorBits={list:[],track:{},sample:0,frame:-1,kicks:0}, cs=G.containers||[], i,j,c,x,y,h;
  for(i=0;i<FLOORBIT_CAP*4&&s.list.length<FLOORBIT_CAP;i++){
