  if(s.frame!==G.frameN){ s.frame=G.frameN; s.kicks=0; }
  if(s.kicks>=12) return 0;
  s.kicks++;
  for(i=0;i<s.list.length;i++){
    b=s.list[i]; dx=b.x-x; dy=b.y-y;
    if(Math.abs(dx)>=r||Math.abs(dy)>=r) continue;
    d=Math.sqrt(dx*dx+dy*dy); if(d>=r) continue;
